SQL_STMT_U.val:
SELECT x.SlipDate, x.SalesSlipNo, x.ProductName, x.OriginType, x.SalesQuantity, x.SalesUnitName, x.UnitPrice, x.UnitPriceTotal, x.TaxMark, CASE WHEN x.ProductName = '前回残高' THEN :4 ELSE @balance := @balance + COALESCE(x.UnitPriceTotal,0) END AS RunningBalance FROM ( /* ① 売上明細 */ SELECT s.sales_date AS SlipDate, s.id AS SalesSlipNo, sd.transaction_specific_product_name AS ProductName, o.origin_name AS OriginType, sd.quantity AS SalesQuantity, u.name AS SalesUnitName, sd.unit_price AS UnitPrice, (sd.quantity * sd.unit_price) AS UnitPriceTotal, CASE WHEN pm.tax_rate_type = 2 THEN '＊' ELSE '' END AS TaxMark, sd.row_no AS LineNo FROM sale_detail sd INNER JOIN sale s ON s.id = sd.sale_id INNER JOIN customer c ON c.id = s.customer_id LEFT JOIN origin o ON o.id = sd.origin_id LEFT JOIN unit u ON u.id = sd.unit_id LEFT JOIN product pm
ON pm.product_cd = sd.product_cd WHERE c.billing_customer_id = :1 AND s.sales_date BETWEEN ':2' AND ':3'
UNION ALL
/* ② 消費税（売上伝票単位）※ 内税は出さない */ SELECT s.sales_date AS SlipDate, s.id AS SalesSlipNo, '消費税' AS ProductName, NULL AS OriginType, NULL AS SalesQuantity, NULL AS SalesUnitName, NULL AS UnitPrice, (COALESCE(s.reduced_tax,0) + COALESCE(s.standard_tax,0)) AS UnitPriceTotal, '' AS TaxMark, 9999 AS LineNo FROM sale s INNER JOIN customer c ON c.id = s.customer_id WHERE c.billing_customer_id = :1 AND s.sales_date BETWEEN ':2' AND ':3' AND c.tax_category <> 2 AND (COALESCE(s.reduced_tax,0) + COALESCE(s.standard_tax,0)) <> 0
UNION ALL
/* ③ 入金 */ SELECT r.receipt_date AS SlipDate, r.id AS SalesSlipNo, '[ 入 金 ]' AS ProductName, NULL AS OriginType, NULL AS SalesQuantity, NULL AS SalesUnitName, NULL AS UnitPrice, -(COALESCE(r.amount,0) + COALESCE(r.fee,0)) AS UnitPriceTotal, '' AS TaxMark, 99999 AS LineNo FROM receipt r WHERE r.billing_customer_id = :1 AND r.receipt_date BETWEEN ':2' AND ':3'
UNION ALL
/* ④ 前回残高 */ SELECT DATE_SUB(':2', INTERVAL 1 DAY) AS SlipDate, NULL AS SalesSlipNo, '前回残高' AS ProductName, NULL AS OriginType, NULL AS SalesQuantity, NULL AS SalesUnitName, NULL AS UnitPrice, NULL AS UnitPriceTotal, '' AS TaxMark, 0 AS LineNo ) AS x JOIN ( SELECT @balance := :4 ) AS init WHERE :1 <> 0 AND ( :4 <> 0 OR EXISTS ( SELECT 1 FROM sale s INNER JOIN customer c ON c.id = s.customer_id WHERE c.billing_customer_id = :1 AND s.sales_date BETWEEN ':2' AND ':3' UNION SELECT 1 FROM receipt r WHERE r.billing_customer_id = :1 AND r.receipt_date BETWEEN ':2' AND ':3' ) ) ORDER BY x.SlipDate, x.SalesSlipNo, x.LineNo;
